// TRUSTED TEST FIXTURE ONLY. This is not generated by CodingAssistant.
(() => {
  'use strict';
  const storageKey = 'ca-calculation-journal-reference-v1';
  const display = document.getElementById('display');
  const previous = document.getElementById('previous');
  const historyPanel = document.getElementById('history');
  const historyList = document.getElementById('history-list');
  let entry = '0';
  let left = null;
  let operator = null;
  let fresh = false;
  let entries = [];
  try {
    const saved = JSON.parse(localStorage.getItem(storageKey) || '[]');
    if (Array.isArray(saved)) {
      entries = saved.filter(item => item && typeof item.result === 'string' &&
        typeof item.expression === 'string').slice(0, 30);
    }
  } catch { entries = []; }

  function render() {
    display.textContent = entry;
    previous.textContent = operator === null ? '' :
      String(left) + ' ' + operator;
    historyList.replaceChildren();
    for (const [index, item] of entries.entries()) {
      const row = document.createElement('li');
      const button = document.createElement('button');
      button.type = 'button';
      button.dataset.historyIndex = String(index);
      button.textContent = item.expression;
      row.append(button);
      historyList.append(row);
    }
  }
  function number(value) {
    if (fresh || entry === 'Error' || entry === 'Cannot divide by zero') {
      entry = value;
      fresh = false;
    } else {
      entry = entry === '0' ? value : entry + value;
    }
    render();
  }
  function decimal() {
    if (fresh || entry === 'Error' || entry === 'Cannot divide by zero') {
      entry = '0.';
      fresh = false;
    } else if (!entry.includes('.')) {
      entry += '.';
    }
    render();
  }
  function setOperation(value) {
    if (entry === 'Error' || entry === 'Cannot divide by zero') return;
    left = Number(entry);
    operator = value;
    fresh = true;
    render();
  }
  function equals() {
    if (left === null || operator === null) return;
    const right = Number(entry);
    const a = left;
    const op = operator;
    left = null;
    operator = null;
    fresh = true;
    if (op === '÷' && right === 0) {
      entry = 'Cannot divide by zero';
      render();
      return;
    }
    const result = op === '+' ? a + right :
      op === '−' ? a - right :
      op === '×' ? a * right :
      op === '÷' ? a / right : NaN;
    if (!Number.isFinite(result)) {
      entry = 'Error';
      render();
      return;
    }
    entry = String(Number(result.toPrecision(12)));
    entries.unshift({
      expression: String(a) + ' ' + op + ' ' + String(right) + ' = ' + entry,
      result: entry,
    });
    entries = entries.slice(0, 30);
    localStorage.setItem(storageKey, JSON.stringify(entries));
    render();
  }
  function clear() {
    entry = '0'; left = null; operator = null; fresh = false; render();
  }
  function backspace() {
    if (fresh || entry === 'Error' || entry === 'Cannot divide by zero') {
      entry = '0'; fresh = false;
    } else {
      entry = entry.length <= 1 || entry.length === 2 && entry[0] === '-' ?
        '0' : entry.slice(0, -1);
    }
    render();
  }
  function recall(item) {
    entry = item.result; left = null; operator = null; fresh = true;
    render();
  }
  function back() {
    if (entries.length) recall(entries[0]);
  }
  document.addEventListener('click', event => {
    const target = event.target.closest('button');
    if (!target) return;
    if (target.dataset.number !== undefined) return number(target.dataset.number);
    if (target.dataset.operation) return setOperation(target.dataset.operation);
    if (target.dataset.historyIndex !== undefined) {
      const item = entries[Number(target.dataset.historyIndex)];
      if (item) recall(item);
      return;
    }
    switch (target.dataset.action) {
      case 'decimal': decimal(); break;
      case 'equals': equals(); break;
      case 'clear': clear(); break;
      case 'backspace': backspace(); break;
      case 'back': back(); break;
      case 'history': historyPanel.hidden = !historyPanel.hidden; break;
    }
  });
  document.addEventListener('keydown', event => {
    if (event.ctrlKey || event.altKey || event.metaKey) return;
    const key = event.key;
    if (/^[0-9]$/.test(key)) number(key);
    else if (key === '.') decimal();
    else if (key === '+') setOperation('+');
    else if (key === '-') setOperation('−');
    else if (key === '*') setOperation('×');
    else if (key === '/') setOperation('÷');
    else if (key === '=' || key === 'Enter') equals();
    else if (key === 'Backspace') backspace();
    else if (key === 'Escape') clear();
    else return;
    event.preventDefault();
  });
  render();
})();
